def check_all_interval_series(arr):
    n = len(arr)
    if sorted(arr) != list(range(n)):
        return False, "Not a permutation of 0 to n-1"

    diffs = []
    for i in range(n - 1):
        diffs.append(abs(arr[i+1] - arr[i]))

    if sorted(diffs) != list(range(1, n)):
        return False, f"Differences are not a permutation of 1 to n-1: {sorted(diffs)}"

    return True, "Valid"

arr = [11, 12, 10, 13, 9, 14, 8, 15, 7, 16, 6, 17, 5, 18, 4, 19, 3, 20, 2, 21, 1, 22, 0, 23]
print(check_all_interval_series(arr))
